          let extra='<g pointer-events="none"><g transform="translate(520,132)"><path d="M-96 52V-4H40V52" fill="#f7f3e8" stroke="#2b2117" stroke-width="2"/><path d="M-108 -4L-28 -48L52 -4" fill="#d6aa4c" stroke="#2b2117" stroke-width="2"/><rect x="36" y="-86" width="30" height="138" fill="#f4efe2" stroke="#2b2117" stroke-width="2"/><path d="M32 -86H70L58 -108H44Z" fill="#5d6a7a" stroke="#2b2117"/><path d="M51 -108V-122M43 -116H59" stroke="#d6aa4c" stroke-width="2.4"/><rect x="-18" y="18" width="26" height="34" fill="#2a2118" stroke="#d6aa4c"/><text x="-28" y="-56" text-anchor="middle" font-family="Almendra SC,serif" font-size="15" fill="#2b2117">Radnica</text></g>';
