          if(wash)extra+='<rect width="1100" height="340" fill="'+wash+'"/>';try{const w=wxOf();if(w==="búrka"||w==="dážď"){extra+='<rect width="1100" height="340" fill="rgba(42,58,78,.4)"/>';extra+=Array.from({length:22},(_,i)=>'<path d="M'+(16+i*50)+' '+(6+(i%3)*12)+'l-14 42" stroke="rgba(226,236,244,.6)" stroke-width="1.2"/>').join("");}}catch(e){}
