    if(typeof vDvor==="function"){const p0=vDvor;vDvor=function(){const h=p0.apply(this,arguments);try{const king=typeof kingD==="function"?kingD():null;const nm=king&&king.head?king.head.name:"kráľ";return hall("Dvor",'<path d="M40 120V40H300V120" fill="#7a1f2b" stroke="#d6aa4c" stroke-width="2"/><path d="M150 40L170 16H190L210 40" fill="#d6aa4c"/>'+folk(170,118,"#7a1f2b",nm,1.1,false)+'<rect x="420" y="70" width="70" height="36" fill="#6b4423" stroke="#d6aa4c" stroke-width="2"/><path d="M430 70V58H480V70" fill="#d6aa4c"/>'+folk(560,118,dynColor(0),P().head.name,.9,false),680,150)+h}catch(e){return h}}}
    if(typeof vCirkev==="function"){const p0=vCirkev;vCirkev=function(){const h=p0.apply(this,arguments);try{const kid=(P().kids||[]).find(k=>k&&(k.path==="cirkev"||k.pathDone==="cirkev"));const habit=kid?folk(460,128,"#2a241e",kid.name,1,true):"";return hall("Dóm",'<path d="M40 130V50H250V130" fill="#f7f3e8" stroke="#2b2117"/><path d="M40 50H250L145 16Z" fill="#4f5d78" stroke="#2b2117"/><path d="M145 16V4M132 14H158" stroke="#d6aa4c" stroke-width="3"/><circle cx="90" cy="40" r="3" fill="#ffb040"/><circle cx="200" cy="40" r="3" fill="#ffb040"/>'+folk(145,128,"#2f6b3a","",1,false)+habit,680,150)+h}catch(e){return h}}}
    if(typeof vKariera==="function"){const p0=vKariera;vKariera=function(){const h=p0.apply(this,arguments);try{return hall("Úrad",'<rect x="80" y="40" width="120" height="70" fill="#6b4423" stroke="#2b2117"/><rect x="100" y="28" width="80" height="16" fill="#d6aa4c"/><path d="M150 28V14" stroke="#d6aa4c" stroke-width="4"/>'+folk(360,120,dynColor(0),P().head.name,1,false),680,140)+h}catch(e){return h}}}
    if(typeof vStat==="function"){const p0=vStat;vStat=function(){const h=p0.apply(this,arguments);try{const lines=Array.from({length:5},(_,i)=>'<path d="M40 '+(36+i*16)+'H520" stroke="#c3ae80"/>').join("");return hall("Účtovná kniha",'<rect x="24" y="16" width="560" height="110" fill="#f8f1df" stroke="#7a1f18" stroke-width="3"/>'+lines+'<text x="48" y="32" font-family="Almendra SC,serif" font-size="16" fill="#7a1f18">Účty rodu '+esc(P().name)+"</text>",620,140)+h}catch(e){return h}}}
    if(typeof vMajetok==="function"){const p0=vMajetok;vMajetok=function(){const h=p0.apply(this,arguments);try{return hall("Truhla",'<rect x="40" y="48" width="160" height="70" rx="4" fill="#6b4423" stroke="#d6aa4c" stroke-width="3"/><path d="M40 48C40 28 200 28 200 48" fill="#8a5a2b" stroke="#d6aa4c"/><rect x="250" y="30" width="90" height="70" fill="#2b4c8f" stroke="#d6aa4c"/><path d="M250 30H340L320 48H270Z" fill="#d6aa4c"/>'+folk(520,120,dynColor(0),P().name,.9,false),680,140)+h}catch(e){return h}}}
